ALTER TABLE public.subscriptions ADD COLUMN is_trial boolean NOT NULL DEFAULT false;
UPDATE public.subscriptions SET is_trial=true WHERE allocation_note LIKE 'Trial · %';
CREATE TABLE public.trial_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), days integer NOT NULL DEFAULT 14 CHECK(days BETWEEN 1 AND 3650), subscription_id uuid REFERENCES public.subscriptions(id), reviewed_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trial_requests TO authenticated; GRANT ALL ON public.trial_requests TO service_role;
ALTER TABLE public.trial_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY trial_request_read ON public.trial_requests FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.trial_activity (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, day date NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,day));
GRANT SELECT ON public.trial_activity TO authenticated; GRANT ALL ON public.trial_activity TO service_role;
ALTER TABLE public.trial_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY trial_activity_read ON public.trial_activity FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION elixir_private.touch_trial_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER touch_trial_request BEFORE UPDATE ON public.trial_requests FOR EACH ROW EXECUTE FUNCTION elixir_private.touch_trial_updated_at();
CREATE TRIGGER touch_trial_activity BEFORE UPDATE ON public.trial_activity FOR EACH ROW EXECUTE FUNCTION elixir_private.touch_trial_updated_at();
CREATE FUNCTION public.request_trial() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Sign in on an active device first'; END IF; IF EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=auth.uid() AND NOT revoked AND starts_at<=now() AND ends_at>now()) THEN RAISE EXCEPTION 'You already have active access'; END IF; INSERT INTO public.trial_requests(user_id) VALUES(auth.uid()) ON CONFLICT(user_id) DO NOTHING; SELECT id INTO rid FROM public.trial_requests WHERE user_id=auth.uid(); RETURN rid; END $$;
CREATE OR REPLACE FUNCTION elixir_private.admin_allocate_trial(_user uuid,_plan text,_days integer,_start date,_note text DEFAULT '',_subscription uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _days IS NULL OR _days<1 OR _days>3650 OR _start IS NULL OR _note IS NULL OR length(_note)>480 THEN RAISE EXCEPTION 'Choose 1–3650 trial days, a start date and a valid note'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user) OR NOT EXISTS(SELECT 1 FROM public.subscription_plans WHERE id=_plan) THEN RAISE EXCEPTION 'Student or plan not found'; END IF; IF _subscription IS NULL THEN INSERT INTO public.subscriptions(user_id,plan_id,starts_at,ends_at,approved_by,amount_paid_paise,allocation_note,is_trial) VALUES(_user,_plan,_start::timestamptz,_start::timestamptz+make_interval(days=>_days),auth.uid(),0,'Trial · '||_note,true) RETURNING id INTO sid; ELSE UPDATE public.subscriptions SET starts_at=_start::timestamptz,ends_at=_start::timestamptz+make_interval(days=>_days),amount_paid_paise=0,allocation_note='Trial · '||_note,is_trial=true WHERE id=_subscription AND user_id=_user AND plan_id=_plan AND payment_request_id IS NULL AND is_trial RETURNING id INTO sid; IF NOT FOUND THEN RAISE EXCEPTION 'Trial not found'; END IF; END IF; UPDATE public.trial_requests SET status='approved',days=_days,subscription_id=sid,reviewed_by=auth.uid() WHERE user_id=_user AND (status='pending' OR subscription_id=sid); RETURN sid; END $$;
CREATE FUNCTION public.admin_review_trial(_request uuid,_days integer DEFAULT 14,_approve boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.trial_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO r FROM public.trial_requests WHERE id=_request FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Request not found'; END IF; IF r.status='approved' THEN RAISE EXCEPTION 'Edit the allocated trial in Subscriptions'; END IF; IF _approve THEN PERFORM elixir_private.admin_allocate_trial(r.user_id,'panacea',_days,current_date,'Requested trial'); ELSE UPDATE public.trial_requests SET status='rejected',reviewed_by=auth.uid() WHERE id=_request; END IF; INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),'review','trial_requests',_request::text,'["status","days"]'); END $$;
CREATE FUNCTION public.record_trial_visit() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Active account required'; END IF; IF EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=auth.uid() AND is_trial AND NOT revoked AND starts_at<=now() AND ends_at>now()) THEN INSERT INTO public.trial_activity(user_id,day) VALUES(auth.uid(),(now() AT TIME ZONE 'Asia/Kolkata')::date) ON CONFLICT(user_id,day) DO UPDATE SET last_seen_at=now(); END IF; END $$;
CREATE FUNCTION public.admin_trial_engagement(_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; RETURN jsonb_build_object('visits',coalesce((SELECT jsonb_agg(x ORDER BY x.day DESC) FROM (SELECT day,last_seen_at FROM public.trial_activity WHERE user_id=_user ORDER BY day DESC LIMIT 90) x),'[]'::jsonb),'questions',(SELECT count(*) FROM public.attempts a WHERE a.user_id=_user AND EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.user_id=_user AND s.is_trial AND a.created_at>=s.starts_at AND a.created_at<s.ends_at)),'correct',(SELECT count(*) FROM public.attempts a WHERE a.user_id=_user AND a.correct AND EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.user_id=_user AND s.is_trial AND a.created_at>=s.starts_at AND a.created_at<s.ends_at))); END $$;
CREATE FUNCTION public.offline_access_grant() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Sign in on an active device'; END IF; IF public.has_role(auth.uid(),'admin') THEN RETURN jsonb_build_object('owner',auth.uid(),'subjects',(SELECT jsonb_agg(jsonb_build_object('subject',subject,'expiresAt',now()+interval '30 days')) FROM public.decks WHERE depth=1)); END IF; RETURN jsonb_build_object('owner',auth.uid(),'subjects',coalesce((SELECT jsonb_agg(jsonb_build_object('subject',subject,'expiresAt',ends_at)) FROM (SELECT ps.subject,max(s.ends_at) ends_at FROM public.subscriptions s JOIN public.plan_subjects ps ON ps.plan_id=s.plan_id WHERE s.user_id=auth.uid() AND NOT s.is_trial AND NOT s.revoked AND s.starts_at<=now() AND s.ends_at>now() GROUP BY ps.subject) x),'[]'::jsonb)); END $$;
CREATE FUNCTION public.admin_save_plan_three_year(_id text,_name text,_description text,_year integer,_two_year integer,_three_year integer,_original_year integer,_original_two_year integer,_original_three_year integer,_enabled boolean,_subjects text[],_perks text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _three_year IS NULL OR _three_year<0 OR (_original_three_year IS NOT NULL AND _original_three_year<_three_year) THEN RAISE EXCEPTION 'Check three-year prices'; END IF; PERFORM public.admin_save_plan_full(_id,_name,_description,_year,_two_year,_original_year,_original_two_year,_enabled,_subjects,_perks); UPDATE public.subscription_plans SET price_three_year=_three_year,original_price_three_year=_original_three_year WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.request_trial(),public.admin_review_trial(uuid,integer,boolean),public.record_trial_visit(),public.admin_trial_engagement(uuid),public.offline_access_grant(),public.admin_save_plan_three_year(text,text,text,integer,integer,integer,integer,integer,integer,boolean,text[],text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_trial(),public.admin_review_trial(uuid,integer,boolean),public.record_trial_visit(),public.admin_trial_engagement(uuid),public.offline_access_grant(),public.admin_save_plan_three_year(text,text,text,integer,integer,integer,integer,integer,integer,boolean,text[],text[]) TO authenticated;